	public class SkillState : State<Player>
	{
		public static string staticID = string.Empty;

		public string skillID = "UnnamedSkill";

		public StatData skillData;

		public ElementType element;

		public bool isUnlocked;

		public bool hasSignatureVariant;

		public bool signatureUnlocked;

		public bool isSignature;

		public int currentLevel;

		public bool isUltimate;

		public BoolVarStat empoweredStat;

		public bool isBasic;

		public bool isDash;

		public bool isMovementSkill;

		public bool isJumpSkill;

		public bool isMeleeSkill;

		public bool isProjectileSkill;

		public bool isBuffSkill;

		public bool isSummonSkill;

		public static int MaxSkillFlags = 8;

		public float currentAnimTime;

		public float animStartTime;

		public float animHoldTime;

		public float animExecTime;

		public float cancelThreshold = 1f;

		public float runThreshold = 1f;

		public float exitThreshold = 1f;

		public Vector2 inputVector;

		public int skillSlot = -1;

		public bool isChargeSkill;

		public bool applyStopElementStatus;

		public bool disableStartCooldown;

		public bool startCooldownOnEnter = true;

		public Cooldown cooldownRef;

		public bool useSmartCD;

		public bool cdStarted;

		public bool allowSelfTransition;

		public bool allowRepeating;

		public bool repeatLock;

		public bool isHoldSkill;

		public bool holdStarted;

		public bool holdReleased;

		public bool updateHoldAnim = true;

		public bool skillExecuted;

		public SkillState prevSkillState;

		private SkillState cancelToDashSkill;

		public virtual bool IsEmpowered => empoweredStat.CurrentValue;

		public virtual string OnEnterAnimStr => parent.NextHandAnimStr;

		public virtual string OnHoldAnimStr => parent.LastHandAnimStr;

		public SkillState(string newName, FSM newFSM, Player newEnt)
			: base(newName, newFSM, newEnt)
		{
			InitializeSkill();
			skillID = newName;
			SetSkillData();
			RegisterSkill();
		}

		public void InitializeSkill()
		{
			currentLevel = 0;
			isUltimate = false;
			isUnlocked = false;
			signatureUnlocked = false;
			empoweredStat = new BoolVarStat(newBaseVal: false);
		}

		public void SetSkillData()
		{
			skillData = StatManager.GetSkillData(parent.skillCategory, skillID);
			if (skillData == null)
			{
				Debug.Log("No skillData found in StatManager for skillID: " + skillID + " in category: " + parent.skillCategory);
				return;
			}
			element = (ElementType)Enum.Parse(typeof(ElementType), skillData.GetValue<string>("elementType"));
			if (!elementSkillDict[element].Contains(skillID))
			{
				elementSkillDict[element].Add(skillID);
			}
		}

		public void RegisterSkill()
		{
			parent.skillsDict[skillID] = this;
			parent.cooldownManager.Add(skillID, skillData.GetValue<float>("cooldown", currentLevel), skillData, this);
			cooldownRef = parent.cooldownManager.cooldowns[skillID];
		}

		public virtual void SetAnimTimes(float newStart = 0f, float newHold = 0.2f, float newExecute = 0.3f, float newCancel = 0.6f, float newRun = 0.8f, float newExit = 1f)
		{
			animStartTime = newStart;
			animHoldTime = newHold;
			animExecTime = newExecute;
			cancelThreshold = newCancel;
			runThreshold = newRun;
			exitThreshold = newExit;
		}

		public void InitChargeSkillSettings(int maxCharges, float delayBetweenCharges, StatData statData, SkillState skillState)
		{
			isChargeSkill = true;
			cooldownRef.isChargeSkill = true;
			cooldownRef.chargeCount = maxCharges;
			cooldownRef.MaxChargeCount = maxCharges;
			cooldownRef.chargeDelayTime = delayBetweenCharges;
			cooldownRef.statData = statData;
			cooldownRef.skillState = skillState;

public class IceDaggerBasic : MeleeAttackState
{
	public new static string staticID = "IceDaggerBasic";

	private string projectileSkillID = "IceDaggerProjectile";

	private Projectile currentProjectile;

	private IceDagger leftAtkObj;

	private IceDagger rightAtkObj;

	private Vector2 atkTransPos;

	private Vector2 perpendVec;

	private Vector3 roteVec;

	public IceDaggerBasic(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isBasic = true;
		isMeleeSkill = true;
		isMovementSkill = true;
		attackPrefab = IceDagger.Prefab;
		destroyAttackObjectOnExit = false;
		maxComboCount = 4;
		animStartTime = 0.12f;
		animExecTime = 0.2f;
		baseCancelThreshold = 0.3f;
		finalCancelThreshold = 0.35f;
		baseRunThreshold = 0.6f;
		finalRunThreshold = 0.8f;
		baseExitThreshold = 1f;
		finalExitThreshold = 1f;
		baseAttackScale = 1.125f;
		penultimateAttackScale = 1.1875f;
		finalAttackScale = 1.25f;
		flipObjectForBackhand = false;
		attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 14f, 10, VarStatModType.OverrideWithMods);
		finalAttackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 18f, 10, VarStatModType.OverrideWithMods);
		autoHoldStat.BaseValue = true;
		sfxNames = new string[maxComboCount];
		for (int i = 0; i < maxComboCount; i++)
		{
			sfxNames[i] = "IceDaggerBasic";
		}
	}

	public override void PlayAnimation(int attackCount)
	{
		flipObjectForBackhand = parent.facingDirection == FacingDirection.Up || parent.facingDirection == FacingDirection.Down;
		base.PlayAnimation(attackCount);
	}

	public override void HandleComboCount(int attackCount)
	{
		base.HandleComboCount(attackCount);
		if (IsEmpowered && calcComboCounter == 0)
		{
			atkTransPos = parent.attackOriginTrans.position;
			perpendVec = Globals.GetPerpendicular(inputVector) * 0.375f;
			if (leftAtkObj != null)
			{
				leftAtkObj.playBreakAnim = false;
				CreateProjectile(perpendVec);
			}
			if (rightAtkObj != null)
			{
				rightAtkObj.playBreakAnim = false;
				CreateProjectile(-perpendVec);
			}
			CameraController.ShakeCamera(0.1f);
		}
	}

	public override void ExecuteAttack()
	{
		if (IsEmpowered)
		{
			atkTransPos = parent.attackOriginTrans.position;
			perpendVec = Globals.GetPerpendicular(inputVector) * 0.35f;
			rotationVector = inputVector;
			if (!parent.isFacingRight)
			{
				rotationVector.x *= -1f;
			}
			roteVec = Globals.GetRotationVector(rotationVector);
			leftAtkObj = CreateAttackObject(atkTransPos + perpendVec);
			rightAtkObj = CreateAttackObject(atkTransPos - perpendVec);
			HandleComboCount(comboCounter);
			HandleSelfTransition(comboCounter);
			AnnounceSkillExecuteEvent();
		}
		else
		{
			base.ExecuteAttack();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		if (IsEmpowered)
		{
			roteVec = Globals.GetRotationVector(inputVector);
			if (!parent.isFacingRight)
			{
				calcScaleVector.x *= -1f;
			}
			ReleaseAttackObject(leftAtkObj);
			ReleaseAttackObject(rightAtkObj);
		}
	}

	private IceDagger CreateAttackObject(Vector2 givenPosition)
	{
		currentAttackObject = Globals.ChaosInst<MeleeAttackObject>(attackPrefab, parent.attackOriginTrans, givenPosition);
		currentAttackObject.attack.SetAttackInfo(parent.skillCategory, skillID, currentLevel);
		currentAttackObject.attack.knockbackOverwriteVector = inputVector;
		currentAttackObject.attackVec = inputVector;
		currentAttackObject.transform.localEulerAngles = roteVec;
		currentAttackObject.transform.localScale = calcScaleVector * scaleValue;
		return currentAttackObject as IceDagger;
	}

	private void ReleaseAttackObject(IceDagger givenDagger)
	{
		if (!(givenDagger == null))
		{
			givenDagger.transform.SetParent(parent.transform.parent);
			givenDagger.transform.localEulerAngles = roteVec;
			givenDagger.transform.localScale = scaleValue * calcScaleVector;
		}
	}

	private void CreateProjectile(Vector2 givenOffset)
	{
		currentProjectile = ChaosInst<Projectile>(IceDaggerProjectile.Prefab, atkTransPos + givenOffset, Globals.GetRotationQuaternion(inputVector));
		currentProjectile.parentObject = parent.gameObject;
		currentProjectile.parentEntity = parent;
		currentProjectile.moveVector = inputVector;
		currentProjectile.attackBox.SetAttackInfo(parent.skillCategory, projectileSkillID, currentLevel);
		currentProjectile.attackBox.knockbackOverwriteVector = inputVector;
		currentProjectile.moveSpeed = 48f;
		currentProjectile.flyTime = 0.25f;
		currentProjectile.disableOnHit = false;
		currentProjectile.transform.localScale *= 1.5f;
		currentProjectile.ignoreReflect = true;
	}
}

	if (animNames != null && animNames.Length > calcComboCounter)
	{
		currentAttackObject.anim.Play(animNames[calcComboCounter], -1, 0f);
	}
}

public virtual void HandleSelfTransition(int attackCount)
{
	if (maxComboCount > attackCount)
	{
		allowSelfTransition = true;
		runThreshold = baseRunThreshold;
		exitThreshold = baseExitThreshold;
	}
	else
	{
		allowSelfTransition = fullAutoStat.CurrentValue;
		runThreshold = finalRunThreshold;
		exitThreshold = finalExitThreshold;
	}
}

public virtual void SetMoveSpeedAndCancelThreshold(int attackCount)
{
	calcComboCounter = maxComboCount - attackCount;
	if (repeatFinalHit)
	{
		calcComboCounter = Mathf.Max(0, calcComboCounter - 1);
	}
	if (calcComboCounter == 0)
	{
		cancelThreshold = finalCancelThreshold;
		parent.movement.moveSpeedStat.AddMod(finalAttackMoveSpeedMod);
	}
	else
	{
		cancelThreshold = baseCancelThreshold;
		parent.movement.moveSpeedStat.AddMod(attackMoveSpeedMod);
	}
}

public virtual bool MovementCheck()
{
	if (ChaosInputDevice.lockControllerAim && !parent.inputDevice.IsMouseAim)
	{
		inputVector = parent.inputDevice.GetAimVector();
		movementVector = parent.inputDevice.GetMoveVector();
		movementApplied = movementVector != Vector2.zero || fsm.previousStateName != name;
	}
	else
	{
		checkAimVec = parent.inputDevice.GetAimVector();
		checkAimUpdated = checkAimVec != Vector2.zero;
		if (checkAimUpdated || fsm.previousStateName != name)
		{
			inputVector = checkAimVec;
		}
		movementVector = checkAimVec;
		movementApplied = checkAimUpdated;
	}
	if (!movementApplied && fsm.previousStateName != name)
	{
		inputVector = Entity.GetFacingDirectionVector(parent.facingDirection);
	}
	if (forceMovement)
	{
		movementApplied = true;
		movementVector = inputVector;
	}
	else if (parent.inputDevice.IsMouseAim && parent.inputDevice.GetMouseDist < minDistForMove)
	{
		return false;
	}
	return movementApplied;
}

public virtual void GetAttackAndMoveVectors(int attackCount)
{
	if (!allowDirectionChange && attackCount > 1)
	{
		if (continueMovement && movementApplied)
		{
			parent.movement.MoveToMoveVector();
		}
	}
	else if (MovementCheck())
	{
		parent.movement.moveVector = movementVector;
		parent.movement.MoveToMoveVector();
	}
}

public virtual void ExecuteAttack()
{
	if (!skipAtkObjSpawn)
	{
		currentAttackObject = Globals.ChaosInst<MeleeAttackObject>(attackPrefab, (!setParent) ? parent.transform.parent : parent.attackOriginTrans, parent.attackOriginTrans.position + spawnOffset);
	}
	HandleComboCount(comboCounter);
	HandleSelfTransition(comboCounter);
	if (!skipAtkObjSpawn)
	{
		currentAttackObject.attack.SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
		currentAttackObject.attack.knockbackOverwriteVector = inputVector;
		currentAttackObject.attackVec = inputVector;
	}
	rotationVector = inputVector;
	if (!parent.isFacingRight && setParent)
	{
		rotationVector.x *= -1f;
	}
	if (!skipAtkObjSpawn)
	{
		currentAttackObject.transform.localEulerAngles = Globals.GetRotationVector(rotationVector);
		currentAttackObject.transform.localScale = calcScaleVector * scaleValue;
	}
	AnnounceSkillExecuteEvent();
}

public override void AnnounceSkillExecuteEvent()
{
	if (!skipAttackEvent)
	{
		base.AnnounceSkillExecuteEvent();
	}
}

public virtual void HandleRepeatLock(bool status, int attackCount)
{
	SetRepeatLock(status);
}

public override void OnEnter()
{
	BaseOnEnter();
	parent.movement.EndMovement();
	if (fsm.previousStateName != fsm.currentStateName)
	{
		comboCounter = 1;
	}
	if (updateSkillLevel)
	{
		SetSkillLevel(comboCounter);
	}
	HandleRepeatLock(!autoHoldStat.CurrentValue, comboCounter);
	SetMoveSpeedAndCancelThreshold(comboCounter);
	GetAttackAndMoveVectors(comboCounter);
	parent.FaceTarget((Vector2)parent.transform.position + inputVector);
	PlayAnimation(comboCounter);
	attackExecuted = false;
	skipAttackEvent = false;
}

public override void Update()
{
	UpdateRepeatLock(string.Empty);
	if (!attackExecuted)
	{
		if (parent.anim.AnimPlayed(animExecTime))
		{
			attackExecuted = true;
			ExecuteAttack();
		}
	}
	else
	{
		ExitToSkillOrRunOrIdle();
	}
}

public override void OnExit()
{
	base.OnExit();
	UpdateRepeatLock(string.Empty);
	parent.movement.moveSpeedStat.RemoveMod(atkMoveModStr);
	comboCounter++;
	if (comboCounter > maxComboCount)
	{
		comboCounter = 1;
	}
	if (!(currentAttackObject != null))
	{
		return;
	}
	if (destroyAttackObjectOnExit)
	{
		UnityEngine.Object.Destroy(currentAttackObject.gameObject);
	}
	else if (setParent)
	{
		currentAttackObject.transform.SetParent(parent.transform.parent);

			cooldownRef.skillState = skillState;
			cooldownRef.remainingTimeStopwatchID = -1;
			cooldownRef.delayStopwatchID = -1;
		}

		public virtual void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			empoweredStat.Modify(givenMod, givenStatus);
			if (parent.skillEmpowerEventHandlers != null)
			{
				parent.skillEmpowerEventHandlers(this);
			}
		}

		public virtual bool IsReady()
		{
			if ((isMovementSkill && !parent.MovementEnabled) || (isUltimate && !IsOverdriveReady()) || (!isUltimate && !cooldownRef.Ready))
			{
				return false;
			}
			if (allowSelfTransition && !allowRepeating && repeatLock)
			{
				return false;
			}
			return true;
		}

		public virtual bool IsOverdriveReady()
		{
			return true;
		}

		public bool Transition()
		{
			if (!IsReady() || (!allowSelfTransition && fsm.currentStateName == skillID))
			{
				return false;
			}
			fsm.ChangeState(skillID, allowSelfTransition: true);
			return true;
		}

		public int SetSkillSlot()
		{
			for (int i = 0; i < parent.assignedSkills.Length; i++)
			{
				if (parent.assignedSkills[i] != null && parent.assignedSkills[i].skillID == skillID)
				{
					skillSlot = i;
					return skillSlot;
				}
			}
			skillSlot = -1;
			return skillSlot;
		}

		public void SetRepeatLock(bool setLock = true)
		{
			repeatLock = setLock;
		}

		public void UpdateRepeatLock(string buttonName = "")
		{
			if (skillSlot != -1)
			{
				if (buttonName == string.Empty)
				{
