	{
		parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animStartTime);
	}

	public override void OnEnter()
	{
		skipAttackEvent = false;
		animExecTime = baseExecTime;
		crestCounter = 1;
		base.OnEnter();
