	}

	public override void ExecuteAttack()
	{
		HandleComboCount(comboCounter);
		HandleSelfTransition(comboCounter);
		AnnounceSkillExecuteEvent();
		bool flag = ((!parent.isFacingRight) ? (!parent.forehandAnimPlayed) : parent.forehandAnimPlayed);
		CreateWaterArc(flag);
		if (DoubleShot)
		{
			CreateWaterArc(!flag);
		}
	}

	private void CreateWaterArc(bool givenArc)
	{
		currentWA = UnityEngine.Object.Instantiate(attackPrefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(inputVector), parent.transform.parent).GetComponentInChildren<WaterArcProjectile>();
		currentWA.parentObject = parent.gameObject;
		currentWA.parentEntity = parent;
		currentWA.targetVector = inputVector;
		currentWA.flyTime = 0.25f;
		currentWA.arcRange = 5f;
		currentWA.positiveApproach = givenArc;
		currentWA.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		currentWA.attackBox.knockbackOverwriteVector = inputVector;
		currentWA.spawnPos = parent.attackOriginTrans.position;
		if (parent.facingDirection == FacingDirection.Up)
		{
			currentWA.sortSpriteLayer.yValueOffset = 0f;
		}
		else if (parent.facingDirection == FacingDirection.Down)
		{
			currentWA.sortSpriteLayer.yValueOffset = 0f;
		}
		else if (givenArc && parent.isFacingRight)
		{
			currentWA.sortSpriteLayer.yValueOffset = -1f;
		}
		else if (!givenArc && !parent.isFacingRight)
		{
			currentWA.sortSpriteLayer.yValueOffset = -1f;
		}
		currentWA.isEmpowered = IsEmpowered;
		Vector3 value = (Vector2)currentWA.transform.position + inputVector * 0.5f + Globals.GetPerpendicular(inputVector) * ((!givenArc) ? 0.75f : (-0.75f));
		WaterDropEmitter poolItem = PoolManager.GetPoolItem<WaterDropEmitter>();
		int? particleCount = 2;
		Vector3? position = value;
		ParticleSystemOverride medWaterExplosionOverride = WaterDropEmitter.MedWaterExplosionOverride;
		poolItem.Emit(particleCount, position, medWaterExplosionOverride, null, 0.1f);
		ParticleEffect poolItem2 = PoolManager.GetPoolItem<ParticleEffect>("WaterHitSmallEffect");
		particleCount = 1;
		position = value;
		Vector3? localEulerAngles = Globals.GetRotationVector(inputVector);
		poolItem2.Emit(particleCount, position, null, localEulerAngles, 0.1f);
	}
