		shieldMod = new NumVarStatMod(staticID, shieldIncrease);
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		shieldMod.modValue = ((!IsEmpowered) ? 25 : 50);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (cooldownReady)
		{
			ApplyStopElement();
			SetShieldStatus(givenStatus: true);
