	public override void FixedUpdate()
	{
		if (currentWB != null)
		{
			currentWB.transform.position = parent.attackOriginTrans.position;
			for (int num = hitEntList.Count - 1; num >= 0; num--)
			{
				if (hitEntList[num] == null)
				{
					hitEntList.RemoveAt(num);
