			currentWB.attackBox.ChangeAttackInfoLevel(2);
			Attack attackBox = currentWB.attackBox;
			attackBox.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attackBox.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnHitTarget));
			currentWB.ignoreProjectileCollisions = false;
			currentWB = null;
			string audioID = "AquaVortex";
			Vector2? soundOrigin = parent.transform.position;
			float overridePitch = UnityEngine.Random.Range(0.85f, 0.95f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		}
	}

	private void SetShieldStatus(bool givenStatus)
	{
		shieldCurrentValue = parent.health.CurrentShieldValue;
		if (givenStatus)
		{
			parent.health.shieldStat.AddMod(shieldMod);
			shieldOriginalValue = shieldCurrentValue;
			shieldIncrease = (int)shieldMod.modValue;
			parent.health.CurrentShieldValue += shieldIncrease;
			return;
		}
		if (shieldCurrentValue > shieldOriginalValue)
		{
			if (shieldCurrentValue > shieldOriginalValue + shieldIncrease)
			{
				parent.health.CurrentShieldValue -= shieldIncrease;
			}
			else if (shieldCurrentValue > shieldOriginalValue)
			{
				parent.health.CurrentShieldValue = shieldOriginalValue;
			}
		}
		parent.health.shieldStat.RemoveMod(shieldMod);
	}

	private void CreateWaterBall()
	{
		currentWB = ChaosInst<WaterBallProjectile>(WaterBallProjectile.Prefab, parent.attackOriginTrans.position);
		currentWB.parentObject = parent.gameObject;
		currentWB.parentEntity = parent;
		currentWB.UpdateCalculatedDamage(initDamageOverride: true);
		currentWB.attackBox.knockbackOverwriteVector = inputVector;
		currentWB.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		currentWB.released = true;
		currentWB.targetHit = true;
		currentWB.maxCharge = hitCount;
		currentWB.currentCharge = hitCount;
		currentWB.disableBlast = true;
		currentWB.hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.0625f, hitCount);
		currentWB.rotation = true;
		currentWB.rotationsPerSecond = ((!(inputVector.x > 0f)) ? 5 : (-5));
		currentWB.projectileSprite.transform.localScale = ((!(inputVector.x > 0f)) ? new Vector3(-1f, 1f, 1f) : Vector3.one);
		currentWB.attackBox.transform.localScale = Vector3.one * 1.5f;
		currentWB.ignoreProjectileCollisions = true;
		currentWB.Show();
		Attack attackBox = currentWB.attackBox;
		attackBox.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attackBox.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnHitTarget));
		Attack attackBox2 = currentWB.attackBox;
		attackBox2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attackBox2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnHitTarget));
		PoolManager.GetPoolItem<WaterDropEmitter>().Emit(10, currentWB.transform.position, WaterDropEmitter.MedWaterExplosionOverride);
	}

	private void OnHitTarget(Entity hitEnt)
	{
		if (!hitEntList.Contains(hitEnt))
		{
			hitEntList.Add(hitEnt);
		}
	}
}

	public class BaseDashState : SkillState
	{
		public bool showEffects = true;

		public bool playSFX = true;

		public bool cooldownReady;

		public bool prevCDWasReady;

		public bool finishedDashing;

		public float dashDuration = 0.125f;

		public NumVarStatMod dashDurationMod;

		public BoolVarStat forceEvadeStat;

		public NumVarStatMod evadeMod;

		public BoolVarStatMod airborneMod;

		public BaseDashState(string skillID, FSM fsm, Player player)
			: base(skillID, fsm, player)
		{
			isDash = true;
			isMovementSkill = true;
			forceEvadeStat = new BoolVarStat(newBaseVal: false);
			evadeMod = new NumVarStatMod("DashEvade", 1f, 10, VarStatModType.Override);
			airborneMod = new BoolVarStatMod(SkillState.staticID, newModValue: true);
			dashDurationMod = new NumVarStatMod("dashOverride", dashDuration, 10, VarStatModType.OverrideWithMods);
		}

		public override bool IsReady()
		{
			return parent.MovementEnabled && (!allowSelfTransition || allowRepeating || !repeatLock) && (!isUltimate || IsOverdriveReady());
		}

		public override void OnEnter()
		{
			if (parent.dashSlideIgnored)
			{
				cooldownReady = prevCDWasReady;
				disableStartCooldown = true;
			}
			else
			{
				cooldownReady = cooldownRef.Ready;
				prevCDWasReady = cooldownReady;
				disableStartCooldown = !cooldownReady;
			}
			parent.dashSlideIgnored = false;
			BaseOnEnter();
			if (forceEvadeStat.CurrentValue)
			{
				parent.health.evadeStat.AddMod(evadeMod);
			}
			finishedDashing = false;
			dashDurationMod.modValue = dashDuration;
			parent.movement.dashDurationStat.AddMod(dashDurationMod);
			parent.movement.dashTimer = dashDuration;
			if (parent.inputDevice == null)
			{
				inputVector = Vector2.zero;
			}
			else if (parent.inputDevice.IsMouseDash)
			{
				inputVector = GetInputVector();
			}
			else
			{
				inputVector = GetInputVector(faceInputVector: true, (parent.inputDevice.inputScheme == ChaosInputDevice.InputScheme.Gamepad && ChaosInputDevice.lockControllerAim) ? true : false);
			}
			parent.movement.dashVector = inputVector;
			parent.anim.PlayDirectional(parent.DashAnimStr);
			if (showEffects && !cooldownReady)
			{
				PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, inputVector);
				parent.dustEmitter.EmitDirBurst(15, Globals.GetRotationVector(-inputVector).z);
				parent.dashTrails.SetActive(value: true);
			}
			if (playSFX)
			{
				SoundManager.PlayWithDistAndSPR("StandardDash", parent.transform.position);
			}
			parent.TogglePreventFallCollider(status: false);
			parent.ToggleEnemyFloorCollisions(status: false);
			parent.airborneStat.AddMod(airborneMod);
			AnnounceSkillExecuteEvent();
		}

		public override void Update()
		{
			if (finishedDashing)
			{
				ExitTransition();
			}
		}

		public override void FixedUpdate()
		{
			if (!finishedDashing)
			{
				finishedDashing = parent.movement.DashToTarget();
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.movement.dashDurationStat.RemoveMod(dashDurationMod.ID);
			DashFinished();
			if (forceEvadeStat.CurrentValue)
			{
				parent.health.evadeStat.RemoveMod(evadeMod);
			}
		}

		public virtual void DashFinished()
		{
			parent.dashTrails.SetActive(value: false);
			parent.TogglePreventFallCollider(status: true);
			parent.airborneStat.RemoveMod(airborneMod);
			parent.ToggleEnemyFloorCollisions();
			parent.movement.EndMovement();
		}

		public virtual void ExitTransition()
		{
			fsm.ChangeState(SlideState.staticID);
		}
	}

using System;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class WaterArcProjectile : Projectile
{
	private bool markForDestroy;

	private bool hitWall;

	public Vector3 spawnPos;

	private static GameObject prefab;

	public Vector2 targetVector;

	public float arcRange;

	public bool positiveApproach = true;

	private int targetStopwatchID;

	private float timePercentage;

	private Vector2 initMoveVector;

	private Vector2 lerpExtVector;

	private float initTimeToTarget;

	private float accuracyOffset = 0.707f;

	private float rotationalAngle;

	private Vector2 rightBound;

	private Vector2 leftBound;

	private Vector3 parentScale;

	public SortSpriteLayer sortSpriteLayer;

	private int waterDropEffectTimer = -1;

	private float waterDropInterval = 0.1f;

	[HideInInspector]
	public bool isEmpowered;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/WaterArc.prefab"));

	public override void Awake()
	{
		base.Awake();
		sortSpriteLayer = transform.parent.GetComponentInChildren<SortSpriteLayer>();
		projectileSprite = transform.parent.Find("ProjectileSprite").gameObject;
		projectileSpriteRenderer = projectileSprite.GetComponent<SpriteRenderer>();
	}

	public override void Start()
	{
		base.Start();
		parentScale = transform.parent.localScale;
		anim = GetComponentInParent<Animator>();
		if (!positiveApproach)
		{
			parentScale.x *= -1f;
			transform.parent.localScale = parentScale;
		}
		initMoveVector = targetVector;
		moveSpeed = Mathf.Max(1f, moveSpeed);
		initTimeToTarget = arcRange / moveSpeed;
		targetStopwatchID = ChaosStopwatch.Begin(initTimeToTarget);
		rotationalAngle = Vector3.Angle(Vector3.up, initMoveVector) * ((float)Math.PI / 180f) * ((!(initMoveVector.x > 0f)) ? 1f : (-1f));
		rightBound = new Vector2(Mathf.Cos(rotationalAngle), Mathf.Sin(rotationalAngle));
		leftBound = new Vector2(Mathf.Cos(rotationalAngle + (float)Math.PI), Mathf.Sin(rotationalAngle + (float)Math.PI));
		if (!isEmpowered)
		{
			waterDropEffectTimer = ChaosStopwatch.Begin(waterDropInterval);
		}
	}

	public bool WaitForDestroy()
	{
		if (markForDestroy)
		{
			if (hitWall || anim.AnimPlayed())
			{
				base.ResetProjectile();
				UnityEngine.Object.Destroy(transform.parent.gameObject);
			}
			return true;
		}
		return false;
	}

	public override void FixedUpdate()
	{
		if (!WaitForDestroy())
		{
			base.FixedUpdate();
		}
	}

	public override void Update()
	{
		if (!WaitForDestroy())
		{
			if (timePercentage < 1f)
			{
				timePercentage = ChaosStopwatch.GetTimePercentage(targetStopwatchID);
				lerpExtVector = accuracyOffset * Vector2.Lerp(rightBound, leftBound, (!positiveApproach) ? (1f - timePercentage) : timePercentage);
				moveVector = (initMoveVector + lerpExtVector).normalized;
			}
			base.Update();
			if (attackBox != null)
			{
				attackBox.knockbackOverwriteVector = moveVector;
			}
			if (!isEmpowered && ChaosStopwatch.Check(waterDropEffectTimer))
			{
				waterDropEffectTimer = ChaosStopwatch.Begin(waterDropInterval);
				PoolManager.GetPoolItem<WaterDropEmitter>().Emit(2, transform.position);
			}
		}
	}

	public override void HandleWallCollision(Collider2D other)
	{
		hitWall = true;
		MarkProjectileForDestroy();
		base.HandleWallCollision(other);
	}

	public override void ResetProjectile()
	{
		if (!hitWall && !markForDestroy)
		{
			MarkProjectileForDestroy();
		}
	}

	public void MarkProjectileForDestroy()
	{
		ChaosStopwatch.Stop(flyStopwatchID);
		ChaosStopwatch.Stop(lifeStopwatchID);
		markForDestroy = true;
		flagForReset = false;
		forcedReturn = false;
		rigidbody2D.velocity = Vector3.zero;
		Vector2 vector = transform.position;
		if (isEmpowered)
		{
			IceBurst.CreateBurst(vector, attackBox.GetAtkInfoAtLevel(2), 1.5f).attack.knockbackOverwriteVector = initMoveVector;
			PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter").Emit(8, vector, ParticleEffectOverrides.Radius2p5);
			PoolManager.GetPoolItem<ParticleEffect>("IcicleFloorBreakEffect").Emit(5, vector);
			string audioID = "IceFormQuick";
			Vector2? soundOrigin = vector;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
		else
		{
			PoolManager.GetPoolItem<ParticleEffect>("WaterExplosion").Emit(1, vector);
			string audioID = "WaterExplode";
			Vector2? soundOrigin = vector;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
	}
}

public class IceDashState : BaseDashState
{
