	public IceDashState(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		InitChargeSkillSettings(2, 0f, skillData, this);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (cooldownReady)
		{
			CreateIceDecoy(parent.transform.position);
			SoundManager.PlayWithDistAndSPR("IceDash", parent.transform.position);
		}
