	public override void OnExit()
	{
		if (cooldownReady && IsEmpowered)
		{
			parent.StartCoroutine(DelayedClone(parent.transform.position));
		}
		base.OnExit();
	}

	private void CreateIceDecoy(Vector2 givenLocation)
	{
		currentID = ChaosInst<IceDecoy>(IceDecoy.Prefab, givenLocation);
		currentID.gameObject.name = skillID + parent.skillCategory;
		currentID.parentEnt = parent;
		currentID.parentGroup = GameController.allies;
		currentID.attack.SetAttackInfo(parent.skillCategory, skillID);
		currentID.duration = 1.5f;
		currentID.facingDirection = parent.facingDirection;
		currentID.isFacingRight = parent.isFacingRight;
		currentID.spriteRenderer.sprite = parent.spriteRenderer.sprite;
		currentID.spriteRenderer.material = new Material(parent.spriteRenderer.material);
		currentID.spriteRenderer.material.SetFloat("_PaletteIndex", 19f);
		currentID.spriteRenderer.material.SetColor("_OutlineColor", Globals.transparentColor);
		currentID.spriteRenderer.material.SetColor("_FlashColor", Color.white);
		currentID.spriteRenderer.material.SetFloat("_FlashAmount", 0f);
		currentID.shadowTrans.localPosition = parent.shadowSprite.transform.localPosition;
		currentID.shadowTrans.localScale = parent.shadowSprite.transform.localScale;
		currentID.hurtBoxTransform.name = "AllyHurtBox";
		currentID.floorContact.name = "AllyFloorContact";
		currentID.floorContact.layer = LayerMask.NameToLayer("AllyFloorContact");
		PoolManager.GetPoolItem<ParticleEffect>("IcicleFloorBreakEffect").Emit(30, givenLocation);
		PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter").Emit(5, givenLocation + Vector2.up * 1.25f, ParticleEffectOverrides.RadiusOne);
		PoolManager.GetPoolItem<ParticleEffect>("IceFloorBurst").Emit(30, givenLocation);
	}

	private IEnumerator DelayedClone(Vector2 givenPosition)
	{
		yield return null;
		CreateIceDecoy(givenPosition);
	}
}

public class FrostWingDash : BaseDashState
{
	public new static string staticID = "FrostWingDash";

	private static float[] spreadArray = new float[3] { 0.225f, 0.525f, 0.9f };

	private FrostWing frostWing;

	private FrostWingProjectile currentFW;

	private List<FrostWingProjectile> fwList = new List<FrostWingProjectile>();

	private Vector2 perpendVec;

	private int shotCount = 2;

	public FrostWingDash(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		isProjectileSkill = true;
		InitChargeSkillSettings(1, 0f, skillData, this);
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		shotCount = ((!IsEmpowered) ? 2 : 3);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (cooldownReady)
		{
			CreateWings(parent.attackOriginTrans.position);
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		if (cooldownReady)
		{
			ReleaseWings();
		}
		fwList.Clear();
	}

	private void CreateWings(Vector2 givenPosition)
	{
		perpendVec = Globals.GetPerpendicular(inputVector);
		for (int i = 0; i < shotCount; i++)
		{
			CreateFW(givenPosition, (perpendVec * spreadArray[i] - inputVector).normalized);
			CreateFW(givenPosition, (perpendVec * (0f - spreadArray[i]) - inputVector).normalized);
		}
		if (frostWing == null)
		{
			frostWing = ChaosInst<FrostWing>(FrostWing.Prefab, givenPosition, Globals.GetRotationQuaternion(inputVector), parent.playerObjTrans);
		}
		frostWing.transform.localEulerAngles = Globals.GetRotationVector(inputVector);
		frostWing.Initialize(parent, parent.attackOriginTrans);
		SoundManager.PlayWithDistAndSPR("IceSwordSwing", givenPosition);
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(12, givenPosition);
	}

	private void CreateFW(Vector2 givenPosition, Vector2 givenVector)
	{
		currentFW = (FrostWingProjectile)Projectile.CreateProjectile(parent, FrostWingProjectile.Prefab, givenPosition - givenVector, Globals.GetRotationQuaternion(givenVector));
		currentFW.InitFollow(parent.attackOriginTrans, givenVector * 0.5f);
		currentFW.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		currentFW.attackBox.knockbackOverwriteVector = givenVector;
		currentFW.moveVector = givenVector;
		fwList.Add(currentFW);
	}

	private void ReleaseWings()
	{
		for (int num = fwList.Count - 1; num >= 0; num--)
		{
			fwList[num].Release();
		}
	}
}

