	}

	public virtual bool OnReflect(Vector2 reflectedMoveVector, float damageModifer)
	{
		if (ignoreReflect)
		{
			return false;
		}
		moveVector = reflectedMoveVector.normalized;
		if (pointTowardMoveVector)
		{
			isPointedAtMoveVector = false;
		}
		parentEntity = null;
		parentObject = null;
		attackBox.damageModifier = damageModifer;
		attackBox.atkInfo.knockbackVector = moveVector;
		attackBox.knockbackOverwriteVector = moveVector;
		return true;
	}

	public virtual void SetTimedIgnoreWalls(float givenTime)
	{
		StartCoroutine(TimedIgnoreWalls(givenTime));
	}

	private IEnumerator TimedIgnoreWalls(float givenTime)
	{
		goThroughWalls = true;
		yield return new WaitForSeconds(givenTime);
		goThroughWalls = false;
	}

