using System;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class CreepingTendril : MonoBehaviour
{
	private static GameObject prefab;

	public bool isEmpowered;

	public Animator anim;

	public Transform attackTrans;

	public Attack attack;

	public BoxCollider2D attackCollider;

	public Transform spriteTrans;

	private float maxTendrilLen = 4f;

	private AttackInfo attackInfo;

	public float maxAtkRange = 1f;

	private float attackWidth = 0.5f;

	private Vector2 initialRotationVec;

	private FacingDirection parentFacingDir;

	private float distToTarget;

	private float lockOnNormalizedTime;

	private Vector3 targetPos;

	public float expandDuration = 1f;

	public float attackDuration = 1f;

	private ChaosQuickStopwatch expandStopwatch;

	private ChaosQuickStopwatch attackStopwatch;

	private bool expandComplete;

	private bool isExpanding;

	private bool attackComplete;

	private bool isFullyExtended;

	private bool queueEndAttack;

	public bool initialAttackMode;

	private CreepingTendril currentCT;

	private float expandPercentage;

	private Vector2 atkSizeVector;

	private Vector2 atkOffsetVector;

	private Vector3 rotationVector;

	public float rotationsPerSecond = 1.2f;

	public bool useRotation = true;

	public bool rotateClockwise = true;

	[HideInInspector]
	public Transform followTrans;

	[HideInInspector]
	public GameObject parentObj;

	[HideInInspector]
	public Health parentHealth;

	[HideInInspector]
	public Vector3 followOffset;

	private WaterDropEmitter waterDropEffect;

	public Transform waterEmitTrans;

	private float prevAnim;

	private string prevAnimName = string.Empty;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/CreepingTendril.prefab"));

	private void Awake()
	{
		Attack attack = this.attack;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetColHit));
		Attack attack2 = this.attack;
		attack2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetColHit));
		Attack attack3 = this.attack;
		attack3.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack3.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetEntHit));
		Attack attack4 = this.attack;
		attack4.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack4.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetEntHit));
	}

	private void Start()
	{
		if (isEmpowered)
		{
			rotationsPerSecond *= 1.7f;
			attackDuration *= 1.5f;
		}
		(expandStopwatch = new ChaosQuickStopwatch(expandDuration)).IsRunning = true;
		attackStopwatch = new ChaosQuickStopwatch(attackDuration);
		attackInfo = attack.atkInfo;
		atkSizeVector = new Vector2(attackWidth, 0.5f);
		atkOffsetVector = new Vector2(0f, 0.25f);
		rotationVector = new Vector3(0f, 0f, rotationsPerSecond * (float)((!rotateClockwise) ? 360 : (-360)));
		isExpanding = true;
		if (initialAttackMode)
		{
			if (parentFacingDir == FacingDirection.Right || parentFacingDir == FacingDirection.Left)
			{
				PlayAnim("AttackRight");
				if (parentFacingDir == FacingDirection.Left)
				{
					spriteTrans.localScale = new Vector3(-1f, 1f, 1f);
					attackTrans.localScale = spriteTrans.localScale;
				}
			}
			else
			{
				PlayAnim("Attack");
			}
			string audioID = "WaterArcBasic";
			Transform originTrans = transform;
			SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		}
		else
		{
			PlayAnim("Expand");
			string audioID = "AquaPrisonImpact";
			Transform originTrans = transform;
			SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		}
	}

	private void PlayAnim(string animName, float normalizedTime = 0f)
	{
		switch (animName)
		{
		case "Expand":
		case "Retract":
		case "Attack":
		case "AttackRight":
			anim.AdjustAnimSpeed(animName, expandDuration);
			break;
		default:
			anim.speed = 1f;
			break;
		}
		prevAnim = Time.time;
		prevAnimName = animName;
		anim.Play(animName, -1, normalizedTime);
	}

	public void Initialize(Vector2 initialRotationVec, FacingDirection facingDir = FacingDirection.Neutral)
	{
		parentFacingDir = facingDir;
		this.initialRotationVec = initialRotationVec;
		spriteTrans.localEulerAngles = Globals.GetRotationVector(initialRotationVec);
		attackTrans.localEulerAngles = spriteTrans.localEulerAngles;
	}

	private void Update()
	{
		if (!initialAttackMode && (parentObj == null || parentHealth == null || (float)parentHealth.CurrentHealthValue <= 0f))
		{
			EndAttack(0f);
		}
		if (queueEndAttack)
		{
			PlayAnim("LockedOn", lockOnNormalizedTime);
		}
	}

	private void FixedUpdate()
	{
		if (queueEndAttack)
		{
			return;
		}
		if (useRotation)
		{
			spriteTrans.Rotate(rotationVector * Time.fixedDeltaTime);
			attackTrans.Rotate(rotationVector * Time.fixedDeltaTime);
		}
		expandPercentage = expandStopwatch.TimePercentage;
		if (!isFullyExtended)
		{
			if (!(expandPercentage >= 1f))
			{
				return;
			}
			isFullyExtended = true;
			attackStopwatch.IsRunning = true;
			if (!initialAttackMode)
			{
				PlayAnim("Expanded");
				if (!rotateClockwise)
				{
					spriteTrans.localScale = Globals.Vector3NegativeX;
				}
				waterDropEffect = PoolManager.GetPoolItem<WaterDropEmitter>();
				waterDropEffect.followTransform = waterEmitTrans;
				waterDropEffect.reqFollowTrans = true;
				waterDropEffect.Play(24f, waterEmitTrans.position);
			}
		}
		else if (!attackComplete)
		{
			if (!attackStopwatch.IsRunning)
			{
				attackComplete = true;
				if (waterDropEffect != null)
				{
					waterDropEffect.Stop();
				}
				isExpanding = false;
				expandStopwatch.IsRunning = true;
				if (!initialAttackMode)
				{
					PlayAnim("Retract");
					expandStopwatch.IsRunning = true;
				}
				else
				{
					EndAttack(0f);
				}
			}
		}
		else if (expandPercentage >= 1f)
		{
			EndAttack(0f);
		}
	}

	private void LateUpdate()
	{
		if (followTrans != null)
		{
			transform.position = followTrans.position + followOffset;
		}
	}

	private void EndAttack(float giveDelay = 0.25f)
	{
		if (!queueEndAttack)
		{
			if (giveDelay == 0f)
			{
				PlayAnim("Hidden");
			}
			queueEndAttack = true;
			attackCollider.enabled = false;
			if (waterDropEffect != null)
			{
				waterDropEffect.Stop();
			}
			UnityEngine.Object.Destroy(gameObject, giveDelay);
		}
	}

	private void OnDestroy()
	{
		Attack attack = this.attack;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetColHit));
		Attack attack2 = this.attack;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetEntHit));
		PoolManager.GetPoolItem<TrailEmitter>("WaterDropTrailEmitter").Emit(transform.position, targetPos, 8 * (int)distToTarget);
	}

	private void OnTargetColHit(Collider2D givenCol)
	{
		if (givenCol == null || givenCol.gameObject == null)
		{
			return;
		}
		attack.ignoreTargetsList.Add(givenCol.gameObject.GetInstanceID());
		if (!queueEndAttack)
		{
			rotationVector = givenCol.transform.position - transform.position;
			rotationVector = rotationVector.normalized;
			spriteTrans.localEulerAngles = Globals.GetRotationVector(rotationVector) - transform.localEulerAngles;
			attackTrans.localEulerAngles = spriteTrans.localEulerAngles;
			useRotation = false;
			PoolManager.GetPoolItem<WaterDropEmitter>().Emit(14, givenCol.transform.position, WaterDropEmitter.LargeWaterExplosionOverride);
			targetPos = givenCol.transform.position;
			distToTarget = Vector2.Distance(targetPos, transform.position);
			lockOnNormalizedTime = Mathf.Clamp(distToTarget / maxTendrilLen, 0f, 1f);
			PlayAnim("LockedOn", lockOnNormalizedTime);
			if (isEmpowered)
			{
				rotationVector *= -1f;
			}
			currentCT = Globals.ChaosInst<CreepingTendril>(Prefab, transform.parent, targetPos, Quaternion.identity);
			currentCT.attack.SetAttackInfo(attack.atkInfo);
			currentCT.attack.ignoreTargetsList = attack.ignoreTargetsList;
			currentCT.followTrans = givenCol.transform;
			currentCT.rotateClockwise = !rotateClockwise;
			currentCT.isEmpowered = isEmpowered;
			currentCT.Initialize(rotationVector);
			currentCT.parentObj = givenCol.gameObject;
			Entity componentInParent = givenCol.transform.GetComponentInParent<Entity>();
			if (componentInParent != null)
			{
				currentCT.parentHealth = componentInParent.health;
			}
			EndAttack();
		}
	}

	private void OnTargetEntHit(Entity givenEnt)
	{
		if (givenEnt != null && givenEnt.dotManager != null)
		{
			givenEnt.dotManager.AddDot(new CreepingTendrilDotEffect(attackInfo.skillCategory, attackInfo.skillID, (!isEmpowered) ? 2 : 3, givenEnt, attackInfo.entity));
		}
	}
}
