	public class UseWaterBlast : SkillState
	{
		public new static string staticID = "UseWaterBlast";

		private WaitForSeconds waitForSummonDelay = new WaitForSeconds(0.0625f);

		private WaterBlast[] waterBlasts = new WaterBlast[12];

		private NumVarStatMod attackMoveSpeedMod;

		private WaterBlast currentWB;

		private bool summonComplete;

		private bool kickStarted;

		private Vector2 currentPosition;

		private WaterBlast empoweredWB;

		private int shieldOriginalValue;

		private bool shieldValueReset;

		private int maxBlastCount = 3;

		private int maxWaveCount = 1;

		private int waveCounter;

		private int waveStopwatchID;

		private bool waveStarted;

		private int minIndex;

		private int maxIndex;

		public override string OnEnterAnimStr => (!isUltimate) ? parent.ForehandAnimStr : parent.KickAnimStr;

		public UseWaterBlast(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			isMeleeSkill = true;
			SetAnimTimes(0.1f, 0.2f, 0.3f, 0.8f, 0.9f);
			attackMoveSpeedMod = new NumVarStatMod(staticID, 12f, 10, VarStatModType.OverrideWithMods);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.ToggleEnemyFloorCollisions(status: false);
			parent.movement.moveSpeedStat.AddMod(attackMoveSpeedMod);
			summonComplete = false;
			kickStarted = false;
			if (IsEmpowered)
			{
				empoweredWB = CreateWaterBlast((Vector2)parent.attackOriginTrans.position + inputVector * 0.5f, inputVector, 2, useLineCast: false);
				empoweredWB.transform.localScale *= 1.25f;
				shieldOriginalValue = parent.health.CurrentShieldValue;
				parent.health.CurrentShieldValue += 50;
				shieldValueReset = false;
				ApplyStopElement();
			}
			maxBlastCount = ((!isUltimate) ? 3 : 12);
			maxWaveCount = ((!isUltimate) ? 1 : 3);
			waveCounter = 0;
			waveStarted = false;
			parent.StartCoroutine(SummonWaterBlasts());
		}

		public override void ExecuteSkill()
		{
			if (CancelToDash())
			{
				summonComplete = true;
			}
			else if (!kickStarted)
			{
				if (summonComplete)
				{
					kickStarted = true;
					if (!isUltimate)
					{
						parent.anim.PlayDirectional(parent.KickAnimStr, -1, 0.1f);
					}
					parent.movement.moveVector = inputVector;
					parent.movement.MoveToMoveVector();
				}
			}
			else
			{
				if (!parent.anim.AnimPlayed(animExecTime))
				{
					return;
				}
				if (!waveStarted)
				{
					waveStarted = true;
					waveStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.1f, maxWaveCount);
					if (IsEmpowered && empoweredWB != null)
					{
						empoweredWB.Blast();
						PoolManager.GetPoolItem<WaterDropEmitter>().Emit(8, empoweredWB.transform.position, WaterDropEmitter.LargeWaterExplosionOverride);
					}
				}
				switch (ChaosStopwatch.CheckInterval(waveStopwatchID))
				{
				case StopwatchState.Ready:
				{
					switch (waveCounter)
					{
					case 0:
						minIndex = 0;
						maxIndex = 3;
						break;
					case 1:
						minIndex = 3;
						maxIndex = 7;
						break;
					case 2:
						minIndex = 7;
						maxIndex = 12;
						break;
					}
					for (int i = minIndex; i < maxIndex; i++)
					{
						if (waterBlasts[i] != null)
						{
							waterBlasts[i].Blast();
						}
					}
					waveCounter++;
					break;
				}
				case StopwatchState.Done:
					CameraController.ShakeCamera(0.75f);
					base.ExecuteSkill();
					ResetShieldValue();
					break;
				}
			}
		}

		public override void OnExit()
		{
			if (!fsm.nextStateName.Contains("Hurt") && !fsm.nextStateName.Contains("Dead"))
			{
				ResetShieldValue();
			}
			parent.ToggleEnemyFloorCollisions();
			parent.movement.moveSpeedStat.RemoveMod(attackMoveSpeedMod);
			summonComplete = true;
			for (int i = 0; i < maxBlastCount; i++)
			{
				if (waterBlasts[i] != null)
				{
					waterBlasts[i].Dissipate();
				}
			}
			if (IsEmpowered && empoweredWB != null)
			{
				empoweredWB.Dissipate();
			}
			base.OnExit();
		}

		private void ResetShieldValue()
		{
			if (IsEmpowered && !shieldValueReset)
			{
				shieldValueReset = true;
				if (parent.health.CurrentShieldValue > shieldOriginalValue)
				{
					parent.health.CurrentShieldValue = shieldOriginalValue;
				}
			}
		}

		private IEnumerator SummonWaterBlasts()
		{
			if (!isUltimate)
			{
				yield return waitForSummonDelay;
			}
			currentPosition = parent.attackOriginTrans.position;
			for (int i = 0; i < 3; i++)
			{
				if (summonComplete)
				{
					yield break;
				}
				waterBlasts[i] = CreateWaterBlast(currentPosition, Globals.GetRotatedCircleVector(12, i - 1, inputVector), 2);
				if (!isUltimate)
				{
					yield return waitForSummonDelay;
				}
			}
			if (isUltimate)
			{
				for (int j = 3; j < 7; j++)
				{
					waterBlasts[j] = CreateWaterBlast(currentPosition, -Globals.GetRotatedCircleVector(17, j + 4, inputVector) * 1.875f, 3);
				}
				for (int k = 7; k < 12; k++)
				{
					waterBlasts[k] = CreateWaterBlast(currentPosition, Globals.GetRotatedCircleVector(22, k - 9, inputVector) * 2.75f, 4);
				}
			}
			summonComplete = true;
			CameraController.ShakeCamera(0.3f);
		}

		private WaterBlast CreateWaterBlast(Vector2 givenPosition, Vector2 givenVector, int givenLevel, bool useLineCast = true)
		{
			if (useLineCast)
			{
				givenPosition = Globals.GetLinecastVector(givenPosition, givenPosition + givenVector * 2.75f, ChaosCollisions.layerUpperWallAndObst);
			}
			currentWB = ChaosInst<WaterBlast>(WaterBlast.Prefab, givenPosition, Globals.GetRotationQuaternion(givenVector));
			currentWB.attack.SetAttackInfo(parent.skillCategory, skillID, 1, isUltimate);
			currentWB.attack.knockbackOverwriteVector = givenVector;
			currentWB.blastSkillLevel = givenLevel;
			PoolManager.GetPoolItem<WaterDropEmitter>().Emit(10, givenPosition, WaterDropEmitter.MedWaterExplosionOverride);
			return currentWB;
		}
	}

