public class FreezingLungeState : SkillState
{
	public new static string staticID = "FreezingLunge";

	private static float velocityMagnitude = 60f;

	private static int ultHitCount = 3;

	private FreezingLungeFist currentFL;

	private Vector2 startPosition;

	private float calcVelocity;

	private float initKbMultiplier;

	private bool dashInitiated;

	private bool attackActivated;

	private bool attackCompleted;

	private int ultCounter;

	private bool ultCompleted;

	private bool movementStopped;

	public override string OnEnterAnimStr => parent.ForehandAnimStr;

	public FreezingLungeState(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		isMovementSkill = true;
		isMeleeSkill = true;
		isHoldSkill = true;
		SetAnimTimes();
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (isUltimate)
		{
			ultCompleted = false;
			ultCounter = 0;
		}
		CreateFreezingLunge((!isUltimate) ? 1 : 3);
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.TogglePreventFallCollider(status: false);
		SetInitVars(velocityMagnitude);
		parent.movement.moveVector = inputVector;
		parent.movement.dashVector = inputVector;
	}

	public override void HandleHoldButton()
	{
		if (!isUltimate || ultCounter <= 0 || !CancelToDash(enableButtonHeld: true))
		{
			holdReleased = parent.anim.AnimPlayed(animExecTime);
		}
	}

	public override void ExecuteSkill()
	{
		if (!dashInitiated)
		{
			dashInitiated = true;
			parent.rigidbody2D.velocity = inputVector * calcVelocity * parent.movement.dashDurationStat.CurrentValue * 8f;
			SoundManager.PlayWithDistAndSPR("IceDash", parent.transform.position);
			if (currentFL != null)
			{
				currentFL.StopEffects();
			}
		}
		if (!attackActivated)
		{
			attackActivated = true;
			if (currentFL != null)
			{
				currentFL.Execute();
			}
		}
		if (!attackCompleted)
		{
			if (parent.anim.AnimPlayed(cancelThreshold))
			{
				attackCompleted = true;
				if (currentFL != null)
				{
					currentFL.Reset();
					currentFL = null;
				}
				ChaosInst<SnowTrail>(SnowTrail.Prefab).EmitTrail(startPosition, parent.attackOriginTrans.position);
			}
			else if (currentFL != null)
			{
				currentFL.attack.atkInfo.knockbackMultiplier = initKbMultiplier * parent.rigidbody2D.velocity.magnitude * 0.025f;
			}
		}
		else if (isUltimate && !ultCompleted)
		{
			ultCounter++;
			switch (ultCounter)
			{
			case 1:
				parent.anim.PlayDirectional(parent.KickAnimStr, -1, 0.2f);
				CreateFreezingLunge(3);
				SetInitVars(velocityMagnitude * 0.5f);
				break;
			case 2:
				parent.anim.PlayDirectional(OnEnterAnimStr, -1, animStartTime);
				CreateFreezingLunge();
				SetInitVars(velocityMagnitude * 0.5f);
				initKbMultiplier *= 1.75f;
				break;
			case 3:
				ultCompleted = true;
				break;
			}
		}
		else
		{
			base.ExecuteSkill();
		}
	}

	public override void ConcludeSkill()
	{
		if (movementStopped)
		{
			base.ConcludeSkill();
		}
		else
		{
			fsm.ChangeState(SlideState.staticID);
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.movement.EndMovement();
		parent.ToggleEnemyFloorCollisions();
		parent.TogglePreventFallCollider(status: true);
		CleanupFist();
	}

	private void CleanupFist()
	{
		if (currentFL != null)
		{
			Attack attack = currentFL.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			currentFL.Reset();
			currentFL = null;
		}
	}

	private void SetInitVars(float givenVelocity)
	{
		calcVelocity = givenVelocity;
		dashInitiated = false;
		attackActivated = false;
		attackCompleted = false;
		holdReleased = false;
	}

	private void CreateFreezingLunge(int givenLevel = 1)
	{
		CleanupFist();
		startPosition = parent.attackOriginTrans.position;
		currentFL = ChaosInst<FreezingLungeFist>(FreezingLungeFist.Prefab, startPosition - inputVector, Globals.GetRotationQuaternion(inputVector));
		currentFL.parentObject = parent.gameObject;
		currentFL.parentEntity = parent;
		currentFL.followTrans = parent.attackOriginTrans;
		currentFL.followOffset = -inputVector;
		currentFL.SetSkillInfo(parent.skillCategory, skillID, givenLevel, isUltimate);
		currentFL.attackVec = inputVector;
		currentFL.isEmpowered = IsEmpowered;
		currentFL.iceShardAttackLevel = 2;
		initKbMultiplier = Mathf.Max(1f, skillData.GetValue<float>(StatData.kbMultiStr, givenLevel));
		if (isUltimate && givenLevel != 1)
		{
			Attack attack = currentFL.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = currentFL.attack;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
		movementStopped = false;
		SoundManager.PlayAudioWithDistance("IceForm", parent.transform.position);
	}

	private void OnTargetHit(Entity entity)
	{
		if (!movementStopped && ultCounter < ultHitCount && !(entity == null) && !(entity is Destructible))
		{
			movementStopped = true;
			parent.movement.EndMovement();
			parent.movement.MoveToMoveVector(6f);
		}
	}
}

using System;
using UnityEngine;

public class FreezingLungeFist : MonoBehaviour
{
	private static GameObject prefab;

	private ChaosQuickStopwatch lifeStopwatch = new ChaosQuickStopwatch(3f);

	private bool resetQueued;

	public GameObject parentObject;

	public Entity parentEntity;

	public Transform followTrans;

	public Vector3 followOffset;

	private ChaosQuickStopwatch followStopwatch = new ChaosQuickStopwatch(0.0625f);

	private Animator anim;

	public Attack attack;

	private CircleCollider2D attackCol;

	private bool attackInitiated;

	public Vector2 attackVec;

	public bool isEmpowered;

	public int iceShardAttackLevel = 2;

	public int iceShardCount = 3;

	private Vector2 currentPosition;

	private Vector2 spawnVector;

	private IceDaggerProjectile spawnedProj;

	private IcicleFormEffect formEffect;

	private string skillCategory = string.Empty;

	private string skillID = string.Empty;

	private int skillLevel;

	private bool skillIsUltimate;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/FreezingLungeFist.prefab"));

	private void Awake()
	{
		anim = GetComponent<Animator>();
		this.attack = transform.Find("Attack").GetComponent<Attack>();
		attackCol = this.attack.GetComponent<CircleCollider2D>();
		Attack attack = this.attack;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(TargetHit));
		Attack attack2 = this.attack;
		attack2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(TargetHit));
	}

	private void Start()
	{
		lifeStopwatch.IsRunning = true;
		formEffect = PoolManager.GetPoolItem<IcicleFormEffect>();
		formEffect.Play(80, -20f, 0.2f, 3f, transform);
		attack.SetAttackInfo(skillCategory, skillID, skillLevel, skillIsUltimate);
		attack.knockbackOverwriteVector = attackVec;
	}

	private void LateUpdate()
	{
		if (followTrans != null)
		{
			transform.position = followTrans.position + Vector3.Lerp(Vector3.zero, followOffset, followStopwatch.TimePercentage);
		}
		if (!resetQueued && !lifeStopwatch.IsRunning)
		{
			Reset();
		}
	}

	public void SetSkillInfo(string givenCategory, string givenID, int givenLevel, bool givenUlt)
	{
		skillCategory = givenCategory;
		skillID = givenID;
		skillLevel = givenLevel;
		skillIsUltimate = givenUlt;
	}

	public void Execute()
	{
		attackInitiated = true;
		attackCol.enabled = true;
		StopEffects();
		followOffset = attackVec * 1.5f;
		followStopwatch.IsRunning = true;
	}

	public void Reset()
	{
		resetQueued = true;
		anim.Play("Break", -1, 0f);
		attackCol.enabled = false;
		if (isEmpowered && attackInitiated)
		{
			SpawnIceShards();
		}
		StopEffects();
		currentPosition = transform.position;
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(10, currentPosition, ParticleEffectOverrides.StartSpeed10);
		string audioID = "IceExplode";
		Vector2? soundOrigin = currentPosition;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		audioID = "IceSolidify";
		soundOrigin = currentPosition;
		standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		if (gameObject != null)
		{
			UnityEngine.Object.Destroy(gameObject, 0.5f);
		}
	}

	private void TargetHit(Collider2D col)
	{
		attack.ignoreTargetsList.Add(col.gameObject.GetInstanceID());
	}

	private void SpawnIceShards()
	{
		currentPosition = transform.position;
		for (int i = 0; i < iceShardCount; i++)
		{
			spawnVector = Globals.GetRotatedCircleVector(30, i - 1, attackVec);
			spawnedProj = Globals.ChaosInst<IceDaggerProjectile>(IceDaggerProjectile.Prefab, null, currentPosition, Globals.GetRotationQuaternion(spawnVector));
			spawnedProj.parentObject = parentObject;
			spawnedProj.parentEntity = parentEntity;
			spawnedProj.moveSpeed = 48f;
			spawnedProj.flyTime = 0.25f;
			spawnedProj.attackBox.SetAttackInfo(skillCategory, skillID, iceShardAttackLevel, skillIsUltimate);
			spawnedProj.attackBox.knockbackOverwriteVector = spawnVector;
			spawnedProj.moveVector = spawnVector;
			if (skillIsUltimate)
			{
				spawnedProj.disableOnHit = false;
			}
			else
			{
				spawnedProj.attackBox.ignoreTargetsList.AddRange(attack.ignoreTargetsList);
			}
		}
	}

	public void StopEffects()
	{
		if (formEffect != null)
		{
			formEffect.Stop();
			formEffect = null;
		}
	}
}
