public class SwordStorm : Projectile
{
	private static GameObject prefab;

	private ParticleEffect snowEffect;

	[HideInInspector]
	public Movement movement;

	[HideInInspector]
	public Transform trackTrans;

	private static int maxHitCount = 7;

	private int hitCount;

	private Vector3 pointingVector;

	public bool isEmpowered;

	private bool isReleased;

	private static AudioSource swordAudioSource;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/SwordStorm.prefab"));

	public override void Awake()
	{
		base.Awake();
		movement = GetComponent<Movement>();
		Attack attack = attackBox;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(IncrementHitCounter));
		Attack attack2 = attackBox;
		attack2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(IncrementHitCounter));
	}

	public override void Start()
	{
		base.Start();
		snowEffect = PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter");
		snowEffect.reqFollowTrans = true;
		snowEffect.followTransform = transform;
		snowEffect.followOffset = (transform.position - transform.TransformPoint(transform.localPosition + Vector3.up * 1.5f)).normalized;
		ParticleEffect particleEffect = snowEffect;
		float? emissionRate = 2f;
		float? playTime = lifeTime;
		particleEffect.Play(emissionRate, null, null, playTime);
	}

	public override void Update()
	{
		base.Update();
		if (!(trackTrans == null) && !isReleased)
		{
			movement.OrbitTarget(trackTrans.position, useTransform: true);
			pointingVector = (transform.position - trackTrans.position).normalized;
			transform.localEulerAngles = Globals.GetRotationVector(pointingVector);
			attackBox.knockbackOverwriteVector = pointingVector;
			if (swordAudioSource == null || !swordAudioSource.isPlaying)
			{
				string audioID = "SwordStorm";
				Transform originTrans = transform;
				swordAudioSource = SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
			}
		}
	}

	private void IncrementHitCounter(Collider2D col)
	{
		if (++hitCount >= maxHitCount)
		{
			ResetProjectile();
		}
	}

	public override void ResetProjectile()
	{
		Attack attack = attackBox;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(IncrementHitCounter));
		if (isEmpowered && !isReleased)
		{
			isReleased = true;
			flyTime = 0.25f;
			RefreshFlightTime();
			moveSpeed = 32f;
			moveVector = pointingVector;
			goThroughWalls = false;
			wallCollider.enabled = true;
			ignoreReflect = false;
			ignoreNegate = false;
			ignoreProjectileCollisions = false;
			snowEffect.Play(25f, playTime: flyTime, position: null, overrides: ParticleEffectOverrides.RadiusOne);
		}
		else
		{
			if (snowEffect != null)
			{
				snowEffect.Stop();
			}
			base.ResetProjectile();
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(10, transform.position);
			SoundManager.PlayAudioWithDistance("Shatter", transform.position);
			if (swordAudioSource != null && swordAudioSource.isPlaying)
			{
				swordAudioSource.Stop();
				swordAudioSource = null;
			}
		}
	}
