using UnityEngine;

public class IceChakram : MonoBehaviour
{
	public Movement movement;

	[HideInInspector]
	public Transform parentTrans;

	public Attack attack;

	private Vector3 rotationVector;

	public float rotationsPerSecond;

	public float maxRadius;

	public float expandRate;

	[HideInInspector]
	public float orbitSpeed = 6f;

	public bool increaseMoveSpeed = true;

	public bool returnToCenter;

	public float minReturnRadius = 3f;

	private bool reverse;

	private ParticleEffect snowEmitter;

	private int spinDelayStopwatchID = -1;

	private float spinDelay = 0.2f;

	private bool spinLerpDone;

	public float resetDelay;

	private int resetStopwatchID;

	private bool resetQueued;

	private static GameObject _prefab;

	private static AudioSource spinAudio;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/IceChakram.prefab");
			}
			return _prefab;
		}
	}

	private void Awake()
	{
		movement = GetComponent<Movement>();
		attack = GetComponentInChildren<Attack>();
	}

	private void Start()
	{
		spinDelayStopwatchID = ChaosStopwatch.Begin(spinDelay);
		rotationVector = new Vector3(0f, 0f, rotationsPerSecond * 120f);
		movement.orbitSpeed = orbitSpeed;
		snowEmitter = PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter");
		snowEmitter.followTransform = transform;
		snowEmitter.Play();
		PlayAudio();
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(7, transform.position, ParticleEffectOverrides.Radius1p5);
	}

	private void FixedUpdate()
	{
		transform.Rotate(rotationVector * Time.fixedDeltaTime);
		if (!spinLerpDone && ChaosStopwatch.Check(spinDelayStopwatchID))
		{
			rotationVector = new Vector3(0f, 0f, rotationsPerSecond * 360f);
			spinLerpDone = true;
		}
		if (parentTrans == null)
		{
			return;
		}
		PlayAudio();
		if (!resetQueued)
		{
			movement.orbitRadius += expandRate * Time.fixedDeltaTime * (float)((!reverse) ? 1 : (-1));
		}
		if (reverse && movement.orbitRadius <= minReturnRadius)
		{
			if (!resetQueued)
			{
				resetQueued = true;
				resetStopwatchID = ChaosStopwatch.Begin(resetDelay);
				return;
			}
			if (ChaosStopwatch.Check(resetStopwatchID))
			{
				ResetChakram();
				return;
			}
		}
		if (movement.orbitRadius >= maxRadius)
		{
			if (returnToCenter)
			{
				reverse = true;
			}
			else
			{
				ResetChakram();
			}
			return;
		}
		if (increaseMoveSpeed)
		{
			movement.moveSpeedStat.SetInitialBaseValue(movement.orbitRadius * 1.6f);
		}
		movement.OrbitTarget(parentTrans.position);
	}

	private void ResetChakram()
	{
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(15, transform.position);
		snowEmitter.Stop();
		StopAudio();
		Object.Destroy(gameObject);
	}

	private void OnDestroy()
	{
		if (snowEmitter != null)
		{
			snowEmitter.Stop();
		}
	}

	private void PlayAudio()
	{
		if (spinAudio == null || !spinAudio.isPlaying)
		{
			string audioID = "BlizzardLoop";
			Transform originTrans = transform;
			spinAudio = SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		}
	}

	private void StopAudio()
	{
		if (spinAudio != null)
		{
			spinAudio.Stop();
			spinAudio = null;
		}
		SoundManager.PlayAudioWithDistance("IceExplode", transform.position, null, 24f, -1f, 1.25f);
	}
}

public class BaseJumpState : SkillState
{
	protected ThrownItem parentThrow;

	protected Vector2 startPosition;

	protected bool useCalcValues;

	protected float jumpRange = 5.5f;

	protected float jumpSpeed = 32f;

	protected float jumpTime = 0.5f;

	protected float jumpHeight = 1f;

	protected float jumpBalance = 0.5f;

	protected bool hasLanded;

	protected bool collidersEnabled;

	protected float landingDelay;

	protected ChaosQuickStopwatch landingStopwatch = new ChaosQuickStopwatch();

	public bool setInputVectorOnEnter = true;

	protected BoolVarStatMod airborneStatMod;

	public BaseJumpState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isMovementSkill = true;
		isJumpSkill = true;
		parentThrow = parent.throwScript;
		airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 3);
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		base.ExecuteSkill();
		if (setInputVectorOnEnter)
		{
			inputVector = GetInputVector();
		}
		startPosition = parent.transform.position;
		parent.spriteRenderer.sortingLayerName = "UI";
		SetThrowValues();
		parentThrow.ThrowToTargetVector(Globals.GetSafeLinecastVector(startPosition, inputVector, jumpRange, ChaosCollisions.layerAllWallAndObst));
		landingStopwatch.SetDelay(landingDelay);
		SoundManager.PlayAudioWithDistance("StandardJump", startPosition);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 50;
		float scale = 0.25f;
		Vector3? emitPosition = startPosition;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		hasLanded = false;
		collidersEnabled = false;
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ThrownItem thrownItem2 = parentThrow;
		thrownItem2.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem2.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ToggleObjects(status: false);
	}

	public override void Update()
	{
		if (hasLanded)
		{
			if (!collidersEnabled)
			{
				collidersEnabled = true;
				ToggleObjects(status: true);
			}
			if (!landingStopwatch.IsRunning)
			{
				ExitToSkillOrRunOrIdle();
			}
		}
	}

	public override void OnExit()
	{
		if (!hasLanded)
		{
			OnLanding();
		}
		base.OnExit();
		ToggleObjects(status: true);
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
	}

	public virtual void OnLanding()
	{
		hasLanded = true;
		landingStopwatch.IsRunning = true;
		parent.spriteRenderer.sortingLayerName = "Actor";
	}

	public virtual void ToggleObjects(bool status)
	{
		parent.airborneStat.Modify(airborneStatMod, !status);
		if (parent.hurtBoxObj != null && parent.hurtBoxObj.activeSelf != status)
		{
			parent.hurtBoxObj.SetActive(status);
		}
		if (parent.floorContact != null && parent.floorContact.activeSelf != status)
		{
			parent.floorContact.SetActive(status);
		}
		parent.TogglePreventFallCollider(status);
	}

	public virtual void SetThrowValues()
	{
		parentThrow.useCalculatedValues = useCalcValues;
		parentThrow.moveSpeed = jumpSpeed;
		parentThrow.baseFlightTime = jumpTime;
		parentThrow.throwHeight = jumpHeight;
		parentThrow.isFallingThreshold = jumpBalance;
	}
}

public class UseWaterSlam : BaseJumpState
{
	public new static string staticID = "UseWaterSlam";

	private bool fallAnimPlayed;

	private bool attackQueued;

	private bool attackFirstFrame;

	private AquaVortexBomb currentAV;

	private WaterBomb currentWB;

	private Vector2 targetPosition;

	public UseWaterSlam(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		isMeleeSkill = true;
		applyStopElementStatus = true;
		SetAnimTimes();
		jumpRange = 0f;
		jumpTime = 0.875f;
		jumpHeight = 4.25f;
		jumpBalance = 0.5f;
		landingDelay = 0.35f;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		parent.anim.PlayDirectional(parent.KickAnimStr, -1, 1f);
		startPosition = parent.transform.position;
		SoundManager.PlayWithDistAndSPR("StandardJump", startPosition);
		attackQueued = false;
		attackFirstFrame = true;
		fallAnimPlayed = false;
		targetPosition = Globals.GetSafeLinecastVector(startPosition, inputVector, 6f, ChaosCollisions.layerAllWallAndObst);
		ThrowVortexBomb(targetPosition);
		CameraController.ShakeCamera(0.2f);
	}

	public override void Update()
	{
		if (!hasLanded)
		{
			if (!fallAnimPlayed && parentThrow.isFalling)
			{
				fallAnimPlayed = true;
				parent.anim.PlayDirectional(parent.FallAnimStr, -1, 1f);
				SetThrowVars(0.125f, jumpHeight, 0f);
				parentThrow.ThrowToTargetVector(targetPosition);
			}
		}
		else if (attackQueued)
		{
			if (attackFirstFrame)
			{
				attackFirstFrame = false;
				parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, animExecTime);
				return;
			}
			attackQueued = false;
			DropWaterBomb();
			if (IsEmpowered)
			{
				for (int i = 0; i < 4; i++)
				{
					ThrowWaterBomb(targetPosition + Globals.GetRotatedCircleVector(4, i, inputVector) * 2.5f);
				}
			}
			CameraController.ShakeCamera();
		}
		else
		{
			if (landingStopwatch.IsRunning && parent.anim.AnimPlayed(cancelThreshold))
			{
				parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, cancelThreshold);
			}
			base.Update();
		}
	}

	public override void OnLanding()
	{
		base.OnLanding();
		attackQueued = true;
		parent.airborneStat.RemoveMod(airborneStatMod);
		parent.TogglePreventFallCollider(status: true);
	}

	private void SetThrowVars(float givenTime, float givenHeight, float givenBalance)
	{
		parentThrow.baseFlightTime = givenTime;
		parentThrow.throwHeight = givenHeight;
		parentThrow.isFallingThreshold = givenBalance;
	}

	private void ThrowVortexBomb(Vector2 givenLocation)
	{
		currentAV = ChaosInst<AquaVortexBomb>(AquaVortexBomb.Prefab, parent.transform.position);
		currentAV.SetSkillData(parent.skillCategory, skillID, 1);
		currentAV.baseFlightTime = 0.3f;
		currentAV.throwHeight = 2f;
		currentAV.ThrowToTargetVector(givenLocation);
	}

	private void ThrowWaterBomb(Vector2 givenLocation)
	{
		currentWB = ChaosInst<WaterBomb>(WaterBomb.Prefab, parent.transform.position);
		currentWB.attack.SetAttackInfo(parent.skillCategory, skillID, 3);
		currentWB.initiateOnStart = true;
		currentWB.baseFlightTime = 0.625f;
		currentWB.throwHeight = 4f;
		currentWB.useCastCircle = false;
		currentWB.transform.localScale *= 0.75f;
		currentWB.blastScale = 0.75f;
		currentWB.ThrowToTargetVector(givenLocation);
	}

	private void DropWaterBomb()
	{
		currentWB = ChaosInst<WaterBomb>(WaterBomb.Prefab, parent.transform.position);
		currentWB.attack.SetAttackInfo(parent.skillCategory, skillID, 2);
		currentWB.initiateOnStart = true;
		currentWB.baseFlightTime = 0f;
	}
}

