	private float waterDropInterval = 0.2f;

	private Vector2 currentPosition;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/AquaPrison.prefab"));

	public override void Awake()
	{
		base.Awake();
		targetEntity = null;
		targetHit = false;
		prisonDone = false;
		releaseAnimPlayed = false;
		if (ignoreKnockbackMod == null)
		{
			ignoreKnockbackMod = new BoolVarStatMod("AquaPrisonSkill", Health.skillIgnoreMod);
		}
	}

	public override void Start()
	{
		base.Start();
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		attackBox.ChangeAttackInfoLevel(3);
		finalAtkInfo = new AttackInfo(attackBox.atkInfo);
		attackBox.ChangeAttackInfoLevel(2);
		baseAtkInfo = new AttackInfo(attackBox.atkInfo);
		attackBox.ChangeAttackInfoLevel(1);
		waterDropEffectTimer = ChaosStopwatch.Begin(waterDropInterval);
		currentPosition = transform.position;
		SoundManager.PlayAudioWithDistance("WaterArcBasic", currentPosition, null, 24f, -1f, 0.8f);
