public class ThrowIceLance : ProjectileHoldAttackState
{
	public new static string staticID = "ThrowIceLance";

	private static int[] shootArr = new int[5] { 2, 1, 3, 0, 4 };

	private NumVarStatMod damageMod;

	private float spearScale = 1f;

	private float spearSpeed = 40f;

	private IceLance[] lanceArray = new IceLance[5];

	private IceLance currentIL;

	private NumVarStatMod ultDmgMod;

	private int ultSpawnCount = 5;

	private int spawnCount;

	private int halfCount;

	private int ultStopwatchID;

	private int ultCounter;

	private bool ultStarted;

	private bool ultCompleted;

	private Vector2 shootVector;

	private Vector2 readyPosition;

	private Vector2 lanceHoldPosition;

	private Vector2 perpendVec;

	private Vector3 rotationVec;

	private bool forceResetOnExit;

	public ThrowIceLance(FSM fsm, Player ent)
		: base(staticID, fsm, ent)
	{
		hasSignatureVariant = true;
		SetAnimTimes(0f, 0.2f, 0.25f);
		projectilePrefab = IceLance.Prefab;
		holdRange = 0.75f;
		updateRotation = true;
		recenterOnRelease = false;
		fireAudioID = "IceSwordSwing";
		damageMod = new NumVarStatMod("emp", 0.2f, 10, VarStatModType.Multiplicative);
		ultDmgMod = new NumVarStatMod("ult", -0.6f, 10, VarStatModType.Multiplicative);
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		if (IsEmpowered)
		{
			skillData.AddMod(StatData.damageStr, damageMod);
			spearScale = 1.25f;
			spearSpeed = 55f;
		}
		else
		{
			skillData.RemoveMod(StatData.damageStr, damageMod.ID);
			spearScale = 1f;
			spearSpeed = 40f;
		}
	}

	public override void OnEnter()
	{
		ultStarted = false;
		ultCompleted = false;
		if (isUltimate)
		{
			skillData.AddMod(StatData.damageStr, ultDmgMod);
			spawnCount = ultSpawnCount;
		}
		else
		{
			spawnCount = 1;
		}
		halfCount = (int)((float)spawnCount * 0.5f);
		base.OnEnter();
	}

	public override void ExecuteSkill()
	{
		parent.ToggleEnemyFloorCollisions(status: false);
		if (isUltimate)
		{
			if (!ultStarted)
			{
				ultStarted = true;
				ultStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.125f, spawnCount);
				ultCounter = 0;
				InitLanceTimers(10f);
			}
			if (!ultCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
				{
				case StopwatchState.Running:
					if (ultCounter < spawnCount)
					{
						lanceArray[shootArr[ultCounter]].transform.position = Vector2.Lerp(lanceArray[shootArr[ultCounter]].transform.position, parent.attackOriginTrans.position, ChaosStopwatch.GetTimePercentage(ultStopwatchID));
					}
					break;
				case StopwatchState.Ready:
					parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
					ShootIceLance(lanceArray[shootArr[ultCounter]], (ultCounter <= 0) ? 0f : UnityEngine.Random.Range(0.03f, 0.15f));
					ultCounter++;
					if (ultCounter >= spawnCount)
					{
						skillData.RemoveMod(StatData.damageStr, ultDmgMod.ID);
						currentIL = (IceLance)base.CreateHoldProjectile();
						currentIL.isLarge = true;
					}
					break;
				case StopwatchState.Done:
					ultCompleted = true;
					ultStopwatchID = ChaosStopwatch.Begin(0.2f);
					break;
				}
				CancelToDash(enableButtonHeld: true);
			}
			else
			{
				parent.anim.PlayDirectional(parent.ForehandAnimStr);
				if (ChaosStopwatch.Check(ultStopwatchID))
				{
					parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
					currentIL.shortWallHitDelay = true;
					ShootIceLance(currentIL);
					SyncLances(currentIL.GetFlyStopwatchID());
					base.ExecuteSkill();
					StartCooldownTimer();
				}
			}
		}
		else
		{
			base.ExecuteSkill();
			ShootIceLance(lanceArray[0]);
			parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
			StartCooldownTimer();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.ToggleEnemyFloorCollisions();
		skillData.RemoveMod(StatData.damageStr, ultDmgMod.ID);
		forceResetOnExit = fsm.nextStateName.Contains("Hurt") || fsm.nextStateName.Contains("Dead");
		if (skillExecuted)
		{
			return;
		}
		for (int i = 0; i < spawnCount; i++)
		{
			currentIL = lanceArray[i];
			if (!(currentIL == null))
			{
				if (forceResetOnExit || !currentIL.thrown)
				{
					currentIL.ResetProjectile();
				}
				else
				{
					currentIL.SetNewTimerIDs(ChaosStopwatch.Begin(0.25f), givenIgnore: true);
				}
			}
		}
	}

	public override Projectile CreateHoldProjectile()
	{
		for (int i = 0; i < spawnCount; i++)
		{
			lanceArray[i] = (IceLance)base.CreateHoldProjectile();
			if (IsEmpowered && !isUltimate)
			{
				lanceArray[i].transform.localScale *= spearScale;
			}
		}
		return null;
	}

	public override void HandleHoldButton()
	{
		inputVector = GetInputVector();
		parent.anim.PlayDirectional(OnHoldAnimStr, -1, 1f);
		holdReleased = !parent.inputDevice.GetButton("Skill" + skillSlot);
		lanceHoldPosition = ((!isUltimate) ? HoldPosition : ((Vector2)parent.attackOriginTrans.position));
		perpendVec = Globals.GetPerpendicular(inputVector);
		rotationVec = Globals.GetRotationVector(inputVector);
		for (int i = 0; i < spawnCount; i++)
		{
			currentIL = lanceArray[i];
			if (!(currentIL == null))
			{
				currentIL.RefreshFlightTime();
				currentIL.transform.position = ((i != 2) ? (lanceHoldPosition + perpendVec * (i - halfCount) + inputVector * (halfCount - Mathf.Abs(i - halfCount))) : HoldPosition);
				currentIL.transform.localEulerAngles = rotationVec;
			}
		}
	}

	private void InitLanceTimers(float givenTime)
	{
		for (int i = 0; i < spawnCount; i++)
		{
			if (lanceArray[i] != null)
			{
				lanceArray[i].SetNewTimerIDs(ChaosStopwatch.Begin(givenTime), givenIgnore: true);
			}
		}
	}

	private void SyncLances(int givenID)
	{
		for (int i = 0; i < spawnCount; i++)
		{
			if (lanceArray[i] != null)
			{
				lanceArray[i].SetNewTimerIDs(givenID, givenIgnore: true);
			}
		}
	}

	private void ShootIceLance(IceLance givenLance, float givenAcc = 0f)
	{
		if (!(givenLance == null) && !givenLance.thrown)
		{
			givenLance.moveSpeed = spearSpeed;
			givenLance.flyTime = 0.4f;
			if (!givenLance.isLarge)
			{
				givenLance.anim.Play("Idle");
			}
			else
			{
				givenLance.anim.Play("IdleLarge");
			}
			givenLance.thrown = true;
			givenLance.isPointedAtMoveVector = false;
			givenLance.transform.position = parent.attackOriginTrans.position;
			shootVector = inputVector;
			if (givenAcc > 0f)
			{
				shootVector = (shootVector + UnityEngine.Random.insideUnitCircle * givenAcc).normalized;
			}
			FireProjectile(givenLance, shootVector, setKnockbackVector: true, 0f, 0f, string.Empty);
			SoundManager.PlayAudioWithDistance((!IsEmpowered) ? "StandardThrow" : "StandardHeavySwing", givenLance.transform.position);
			CameraController.ShakeCamera(0.25f);
		}
	}
}

