using UnityEngine;

public class IceLance : Projectile
{
	private static GameObject prefab;

	private List<Entity> hitList = new List<Entity>();

	private Entity tempEnt;

	private float inRangeDist = 3f;

	private bool hitWall;

	public bool thrown;

	private Vector2 dragVector;

	[HideInInspector]
	public bool isLarge;

	private ParticleEffect snowEffect;

	private IcicleFormEffect formEffect;

	private AttackInfo wallAtkInfo;

	private AttackInfo resetAtkInfo;

	[HideInInspector]
	public bool shortWallHitDelay;

	[HideInInspector]
	public bool ignoreWallRefresh;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/IceLance.prefab"));

	public override void Start()
	{
		base.Start();
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(GrabTargetOnContact));
		Attack attack2 = attackBox;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(GrabTargetOnContact));
		SoundManager.PlayWithDistAndSPR("IceFormQuick", transform.position);
		formEffect = PoolManager.GetPoolItem<IcicleFormEffect>();
		formEffect.Play(40, -20f, 0.2f, 3f, transform);
		wallAtkInfo = attackBox.GenerateAttackInfo(attackBox.statData, 2, attackBox.atkInfo.isUltimate);
		resetAtkInfo = attackBox.GenerateAttackInfo(attackBox.statData, 3, attackBox.atkInfo.isUltimate);
	}

	public override void Update()
	{
		if (formEffect != null && anim.AnimPlayed(0.8f))
		{
			StopEffect();
		}
		if (thrown && snowEffect == null)
		{
			snowEffect = PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter");
			snowEffect.reqFollowTrans = true;
			snowEffect.followTransform = transform;
			ParticleEffect particleEffect = snowEffect;
			float? emissionRate = 40f;
			float? playTime = lifeTime;
			particleEffect.Play(emissionRate, null, null, playTime);
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(5, transform.position);
		}
		if (!hitWall)
		{
			dragVector = moveVector * moveSpeed;
			for (int num = hitList.Count - 1; num >= 0; num--)
			{
				tempEnt = hitList[num];
				if (tempEnt == null || tempEnt.hurtBoxTransform == null || Vector2.Distance(tempEnt.hurtBoxTransform.position, transform.position) > inRangeDist)
				{
					hitList.RemoveAt(num);
				}
				else
				{
					tempEnt.rigidbody2D.velocity = dragVector;
				}
			}
		}
		base.Update();
	}

	public override void HandleWallCollision(Collider2D other)
	{
		if (hitWall)
		{
			return;
		}
		hitWall = true;
		projectileLight.SetActive(value: false);
		attackBox.knockbackOverwriteVector = moveVector;
		transform.position += (Vector3)moveVector * 0.25f;
		moveVector = Vector2.zero;
		foreach (Entity hit in hitList)
		{
			if (hit != null)
			{
				hit.rigidbody2D.velocity = Vector2.zero;
				hit.health.TakeDamage(wallAtkInfo);
			}
		}
		attackBox.gameObject.SetActive(value: false);
		if (!ignoreWallRefresh)
		{
			flyTime = ((!shortWallHitDelay) ? 0.35f : 0.125f);
			RefreshFlightTime();
		}
		base.HandleWallCollision(other);
	}

	public override void ResetProjectile()
	{
		if (hitWall)
		{
			foreach (Entity hit in hitList)
			{
				if (hit != null)
				{
					hit.rigidbody2D.velocity = Vector2.zero;
					hit.health.TakeDamage(resetAtkInfo);
				}
			}
		}
		StopEffect();
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(GrabTargetOnContact));
		base.ResetProjectile();
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(30, transform.position);
		SoundManager.PlayWithDistAndSPR("IceExplode", transform.position);
		hitList.Clear();
	}

	private void GrabTargetOnContact(Entity hitEntity)
	{
		if (!hitWall && !(hitEntity == null) && !hitList.Contains(hitEntity) && !(hitEntity.rigidbody2D == null) && hitEntity.rigidbody2D.bodyType == RigidbodyType2D.Dynamic && !(hitEntity.health == null) && !hitEntity.health.invulnerable)
		{
			hitList.Add(hitEntity);
			if (hitEntity.health.ignoreGrab || hitEntity.health.IgnoreKnockback)
			{
				hitWall = true;
				ResetProjectile();
			}
		}
	}

	private void StopEffect()
	{
		if (formEffect != null)
		{
			formEffect.Stop();
			formEffect = null;
		}
		if (snowEffect != null)
		{
			snowEffect.Stop();
			snowEffect = null;
		}
	}

	public void SetNewTimerIDs(int givenID, bool givenIgnore = false)
	{
		flyStopwatchID = givenID;
		lifeStopwatchID = givenID;
		ignoreWallRefresh = givenIgnore;
	}

	public int GetFlyStopwatchID()
	{
		return flyStopwatchID;
	}
}

